+++ b/src/edge-session.ts
@@ -0,0 +1,24 @@
+import { CacheStore, CachedSession, SESSION_CACHE_PREFIX } from "./cache.ts";
+
+export interface EdgeSession {
+  id: string;
+  userId: string;
+}
+
+export const loadSessionFromCache = async (
+  cache: CacheStore,
+  sessionId: string,
+): Promise<EdgeSession | null> => {
+  const key = SESSION_CACHE_PREFIX + sessionId;
+  const cached = await cache.get(key);
+
+  if (!cached) return null;
+
+  const session: CachedSession = JSON.parse(cached);
+  if (!session.isValid) return null;
+
+  return {
+    id: sessionId,
+    userId: session.userId,
+  };
+};
