+// Example edge worker that validates sessions without Postgres access
+// This runs in the CDN's point of presence with access to distributed cache only
+
+import { loadSessionFromCache } from "./edge-session.ts";
+import { CacheStore } from "./cache.ts";
+
+// The edge worker receives a cache implementation specific to the CDN environment
+// This could be Cloudflare KV, S3, a local Redis connection, etc.
+export async function handleRequest(
+  request: Request,
+  cache: CacheStore,
+): Promise<Response> {
+  const sessionId = getSessionIdFromCookie(request);
+
+  if (!sessionId) {
+    return new Response("Unauthorized", { status: 401 });
+  }
+
+  const session = await loadSessionFromCache(cache, sessionId);
+
+  if (!session) {
+    return new Response("Unauthorized", { status: 401 });
+  }
+
+  // Session is valid and not revoked (verified against cache)
+  // Proceed with serving the read API
+  return new Response(
+    JSON.stringify({ userId: session.userId, message: "API response" }),
+  );
+}
+
+function getSessionIdFromCookie(request: Request): string | null {
+  const cookie = request.headers.get("cookie");
+  if (!cookie) return null;
+
+  const sessionMatch = cookie.match(/session=([^;]+)/);
+  return sessionMatch ? sessionMatch[1] : null;
+}
